// routes/settings/action.ts
import type { DataArgs } from "@kasperrt/smolter/react";
import { settings } from "../../server/settings";

export async function action({ request, signal }: DataArgs) {
  const form = await request.formData();
  const displayName = String(form.get("displayName") ?? "").trim();

  if (displayName.length < 2) {
    return { ok: false as const, error: "Use at least two characters." };
  }

  const saved = await settings.saveForRequest(request, { displayName, signal });

  if (saved instanceof Error) return saved;

  return { ok: true as const, displayName: saved.displayName };
}

