import type { ClientActionArgs } from "@kasperrt/smolter/react";
import type { action } from "./action";

export async function clientAction({
  serverAction,
}: ClientActionArgs<typeof action>) {
  const result = await serverAction();

  if (result.ok) sessionStorage.removeItem("settings-draft");

  return result;
}

